    "company": "Chura Abugida Artistic Association (CAAA)",
    "source": "EthioJobs",
    "title": "CALL FOR CONSULTANCY SERVICES Shared Space, Shared Futures (3SF): Advancing Social Cohesion and Civic Participation in Post-Conflict Ethiopia",
    "location": "Tigray",
    "mode": "Onsite",
    "type": "Full-time Entry Level",
    "experience": "0-2 Years",
    "industry": "Tech",
